"""Runtime entry point for the whole-model decode megakernel (MD2 + MD3).

The kestrel engine imports THIS module (never ``mkl``) to run an entire model's decode step in one
persistent CUDA launch, in place of the native ``text_decoder`` forward. The engine's contract is a
cheap GATE plus a builds-lazily RUN, so the megakernel decision can be lifted ABOVE the CUDA-graph
machinery (the engine skips native graph capture for a served bucket and routes it to the eager
megakernel instead)::

    tgt = kestrel_kernels.megakernel.deploy_target(model_name, device)   # (model_kind, arch, num_sms) | None
    if tgt is not None and kestrel_kernels.megakernel.has_megakernel(*tgt, bucket):
        # served: SKIP native graph capture for this bucket, run the megakernel eagerly each step
        hidden = kestrel_kernels.megakernel.decode(
            model_name=..., text=..., text_config=..., device=..., page_table=...,
            max_seq_length=..., batch_size=bucket, embeds=...,
            batch_idx=..., input_pos=..., batch_idx_cpu=..., input_pos_cpu=...)
    else:
        hidden = text_decoder(...)          # native (captured into the decode graph as before)

``has_megakernel`` is the cheap, no-build ship predicate: ``True`` when the enable table admits this
``(model_kind, arch, num_sms, bucket)`` and the compiler catalog selects an exact packed artifact.
It NEVER builds and NEVER raises, so the engine resolves its eager buckets once at initialization.
``deploy_target`` resolves
the device to ``(model_kind, arch, num_sms)`` (or
``None`` when no variant fits: unsupported GPU / model). All deployment policy (eligibility, the
per-bucket enable table, the deploy-SM selection, the lazy per-bucket session build, the paged-KV
args, the eager launch) lives HERE, so the engine carries zero megakernel policy.

``decode`` runs one whole-model decode step and returns the decoder's final hidden ``[B, 1, H]``. It
BUILDS the session lazily on the first call for a bucket (weight-stacking + tape + persistent
buffers), so that first call includes a bundle load; every later step reuses the built session and is
one eager launch. A per-step eligibility miss raises ``MegakernelNotEligible`` so the engine can run
native eagerly for that step. Genuine internal errors remain fatal.

Two backends can serve a session (``build_decode_session`` picks the first available):
  1. The shipped bundle -- the kestrel-kernels wheel bakes the megakernel cubin + tape + launch
     metadata (emitted at BUILD time by ``scripts/precompile``); a production host consumes them with
     no ``mkl`` present (see ``kestrel-kernels/docs/MEGAKERNEL_RUNTIME.md``).
  2. The mkl dev backend -- on a developer checkout with ``mkl`` installed, the session is JIT-built
     from ``mkl.megakernel.decode_bridge``. ``mkl`` is OPTIONAL: absent -> no megakernel here (native).

Importing this module never imports ``mkl``; the dev backend is imported lazily inside
``build_decode_session`` only when no bundle is available, so ``mkl`` is never a hard runtime dep.

Paged KV. Both model families read and append the engine's paged KV pool directly. The compiler
declares compact-row indirection through ``batch_idx``; the VM applies it to the engine's global page
table on device. Native and megakernel decode therefore consume the same page table, row selector,
and position tensor.
"""
from __future__ import annotations

import logging
from dataclasses import asdict, dataclass, field
from collections.abc import Mapping
from functools import lru_cache
from typing import Any, Optional
from weakref import WeakKeyDictionary, ref

import torch

from kestrel_kernels.deploy_targets import (
    WHOLE_MODEL,
    deploy_sm_counts_for,
    select_deploy_num_ctas,
)

logger = logging.getLogger(__name__)


# --------------------------------------------------------------------------------------
# Deploy-SM policy.
#
# Public compatibility view, derived from the packaging-owned whole-model
# target inventory rather than a runtime-side copy.
DEPLOY_SM_COUNTS = deploy_sm_counts_for(WHOLE_MODEL)


def select_num_ctas(arch_num: int, device_sms: int) -> Optional[int]:
    """The persistent-grid size (``num_ctas``) for the megakernel on this device: the largest shipped
    SM count for this arch that is ``<= device_sms``. When that is SMALLER than the device (no exact-fit
    bundle), we warn once and run the next-smaller shipped grid, leaving the surplus SMs idle rather
    than not deploying at all. ``None`` -- run native decode -- when the arch has no megakernel, the SM
    count is non-positive, or no shipped grid fits (the device is smaller than every shipped grid)."""
    chosen = select_deploy_num_ctas(WHOLE_MODEL, arch_num, device_sms)
    if chosen is None:
        return None
    if chosen != int(device_sms):
        logger.warning(
            "megakernel: no bundle matches this device's %d SMs (arch %d); using the largest shipped "
            "grid that fits (%d SMs) -- %d SM(s) will be idle.",
            int(device_sms), int(arch_num), chosen, int(device_sms) - chosen)
    return chosen


class MegakernelNotEligible(RuntimeError):
    """The selected megakernel cannot serve this model or decode step."""


@dataclass(frozen=True)
class MegakernelDecodeConfig:
    """MoE-engine knobs for the decode. Defaults are the MD3 production path (qmma up-projection,
    tensor-core down-projection streamed from memory. Attention partitioning is compiler-owned and
    is not a runtime configuration field. MD2 is dense and ignores the MoE knobs."""
    # NB: NO ``qmma_moe`` knob -- the MoE engine is qmma-only now (the scalar/flat batch arm was
    # deleted from the mkl config), so forwarding a ``qmma_moe`` here would raise a TypeError when
    # ``_to_backend_config`` builds the mkl ``MegakernelDecodeConfig`` (which has no such field). The
    # batch VM always runs the fp8 tensor-core MoE. ``test_megakernel_config_schema_parity`` pins that
    # every field forwarded here is a real mkl config field, so the next deleted knob can't drift.
    stream_moe_down: bool = True
    stream_moe_b: bool = False
    # qmma NS (num-stages) compile constexpr; per-(bucket,SKU). Default 3 = H100 SXM winner; the enable
    # table sets it per variant. Replaces the old MD3_QMMA_NS env var.
    qmma_num_stages: int = 3


@dataclass
class _DecodeStep:
    """Inputs for one decode token (internal).

    ``position_cpu`` is the scheduler-side host value of ``position[0]`` (from
    the engine's ``input_pos_cpu`` staging -- no device read). The generated
    backend derives its per-launch ``kv_len`` scalar from it sync-free; hand-VM
    sessions ignore it because their positions are device-owned."""

    embed: torch.Tensor
    position: torch.Tensor
    position_cpu: Optional[int] = None


# ======================================================================================
# Backend selection (bundle -> mkl dev) -- builds one session; never imports mkl eagerly.
# ======================================================================================
def _bundle_backend_available() -> bool:
    """Whether the shipped-bundle launch path is importable + this host has CUDA. The concrete
    per-model bundle presence check runs inside ``build_decode_session``; this is the cheap capability
    gate. Importing ``bundle_backend`` never imports ``mkl``."""
    if not torch.cuda.is_available():
        return False
    try:
        from . import bundle_backend
    except Exception:
        return False
    return bundle_backend is not None


def _mkl_backend() -> Any:
    """Import the mkl dev backend lazily. Raises ``MegakernelNotEligible`` when mkl is not installed
    -- treated as 'no megakernel here'."""
    try:
        from mkl.megakernel import decode_bridge as backend
    except Exception as exc:  # mkl is optional: absent -> native decode
        raise MegakernelNotEligible(
            f"no shipped megakernel bundle, and the mkl dev backend is unavailable "
            f"({type(exc).__name__}: {exc})"
        ) from exc
    return backend


def _to_backend_config(backend: Any, config: Optional[MegakernelDecodeConfig]) -> Any:
    """Translate our config into the backend's config type (same field names), so callers never
    construct an mkl object directly."""
    if config is None:
        return None
    return backend.MegakernelDecodeConfig(**asdict(config))


def build_decode_session(
    model_kind: str,
    text: Any,
    tc: Any,
    dec_embed0: Optional[torch.Tensor],
    page_table: Any,
    batch_idx: torch.Tensor,
    *,
    batch_bucket: int,
    seqlen: int,
    device: Optional[torch.device] = None,
    ctas_per_row: Optional[int] = None,
    compiler_kind: Optional[str] = None,
    config: Optional[MegakernelDecodeConfig] = None,
    kv_capacity: Optional[int] = None,
    input_pos: Optional[torch.Tensor] = None,
    runtime_tensors: Optional[Mapping[str, torch.Tensor]] = None,
) -> Any:
    """Build the decode session for one model kind ('moondream2' / 'moondream3') and batch bucket.
    ``dec_embed0=None`` (the engine path) makes the session allocate a zero placeholder -- ``decode``
    overwrites the resident embedding every step, so it never reaches an output. Returns a session
    exposing ``.decode(step, batch_idx)`` (+ MD2 ``.seed_kv_from_paged(...)`` and ``.input_pos``).
    Raises ``MegakernelNotEligible`` when no backend fits this device."""
    # Production path: consume the shipped bundle (no mkl). STRUCTURAL SELECTION -- the bundle is used
    # iff its baked spec EXACTLY matches the spec this ``config`` (+ model geometry) requests; any
    # requested knob the bundle wasn't baked with (a non-default ``stream_moe_down`` / ``stream_moe_b``
    # / ``qmma_num_stages``, or LoRA) makes the specs differ and the caller
    # falls through to the mkl JIT backend, which compiles the requested config. There is no
    # hand-written config predicate: ``bundle_available`` compares serialized specs.
    if compiler_kind is None:
        compiler_kind = _registered_compiler_kind(model_kind)
    if (
        runtime_tensors is None
        and compiler_kind is not None
        and ctas_per_row is not None
        and _bundle_backend_available()
    ):
        from . import bundle_backend
        try:
            if bundle_backend.bundle_available(
                    compiler_kind, tc, int(ctas_per_row), config,
                    static_extent_bindings={"active_batch": int(batch_bucket)}):
                return bundle_backend.build_decode_session(
                    model_kind, text, tc, dec_embed0, page_table, batch_idx,
                    compiler_kind=compiler_kind,
                    batch_bucket=int(batch_bucket), seqlen=int(seqlen),
                    input_pos=input_pos,
                    num_ctas=int(ctas_per_row), config=config,
                    kv_capacity=(int(kv_capacity) if kv_capacity is not None else None))
        except bundle_backend.MegakernelNotEligible:
            pass  # no matching bundle here -> try the dev backend / native fallback
    backend = _mkl_backend()
    try:
        return backend.build_decode_session(
            model_kind, text, tc, dec_embed0, page_table, batch_idx,
            batch_bucket=int(batch_bucket), seqlen=int(seqlen), device=device,
            ctas_per_row=ctas_per_row, config=_to_backend_config(backend, config),
            kv_capacity=(int(kv_capacity) if kv_capacity is not None else None),
            input_pos=input_pos,
            runtime_tensors=runtime_tensors)
    except backend.MegakernelNotEligible as exc:
        raise MegakernelNotEligible(str(exc)) from exc


# ======================================================================================
# Deployment policy: model map + the per-(model, arch, num_sms, bucket) enable table.
# ======================================================================================
# The megakernel serves at most 8 rows per launch; the enable table restricts further.
_MAX_MEGAKERNEL_BUCKET = 8


@dataclass(frozen=True)
class _EnableRow:
    """One ``(model, arch, num_sms)`` row of the enable table: which decode buckets are enabled, the
    compiler registration they use, the measurement that justifies them, and per-variant qmma NS."""

    compiler_kind: str
    buckets: frozenset[int] = field(default_factory=frozenset)
    note: str = ""
    qmma_num_stages: int = 3


# Which decode buckets route through the megakernel, per (model, arch, grid size, bucket). Being
# buildable is not the same as being faster (H100 SXM: MD3 batch 1 is 1.38x but batch 8 is 0.86x), so
# only buckets measured at >= 1.0x are enabled. A missing entry / empty set means native (non-fatal).
#
#   model_kind -> arch (SM major * 10) -> grid size (num_sms) -> _EnableRow
_ENABLE_TABLE: dict[str, dict[int, dict[int, _EnableRow]]] = {
    "moondream3": {
        90: {
            132: _EnableRow(
                compiler_kind="md3",
                buckets=frozenset({1}),
                qmma_num_stages=3,  # SXM winner (NS=2 regresses SXM +70.7us @ B8; PCIe bs1 wanted NS=2)
                note=(
                    "H100 SXM: batch 1 is 1.38x (~1917us vs 2306us native). Batches 2/4 are ~1.0x "
                    "(deferred). Batch 8 is 0.86x -> native."
                ),
            ),
        },
    },
    "moondream2": {
        90: {
            132: _EnableRow(
                compiler_kind="md2",
                buckets=frozenset({1, 2}),
                note=(
                    "H100 SXM shipped-AOT+lm_head/native-graph, 200 same-session replays at "
                    "seqlen 16: B1 1.255x, B2 1.203x, B4 1.137x, B8 1.018x. At ChartQA "
                    "CoT history S=751: B1 1.159x, B2 1.064x, B4 0.872x, B8 0.652x; only "
                    "B1/B2 ship. Cosine >=0.999874 and argmax matches native. Uses "
                    "compiler-derived attention partitioning."
                ),
            ),
        },
    },
}


def _registered_compiler_kind(model_kind: str) -> Optional[str]:
    """The unique compiler registration for one deployment policy key, or no packed path."""
    kinds = {
        row.compiler_kind
        for per_sms in _ENABLE_TABLE.get(model_kind, {}).values()
        for row in per_sms.values()
    }
    return next(iter(kinds)) if len(kinds) == 1 else None


def _model_kind(model_name: str) -> Optional[str]:
    """Map an engine model name ('moondream3-preview', 'moondream2', ...) to the enable-table key, or
    ``None`` when the model has no megakernel."""
    name = (model_name or "").lower()
    if name.startswith("moondream3"):
        return "moondream3"
    if name.startswith("moondream2"):
        return "moondream2"
    return None


def _enable_row(model_kind: str, arch: int, num_sms: int) -> Optional[_EnableRow]:
    return _ENABLE_TABLE.get(model_kind, {}).get(int(arch), {}).get(int(num_sms))


def _enabled_buckets(model_kind: str, arch: int, num_sms: int) -> frozenset[int]:
    row = _enable_row(model_kind, arch, num_sms)
    if row is None:
        return frozenset()
    return frozenset(b for b in row.buckets if 1 <= int(b) <= _MAX_MEGAKERNEL_BUCKET)


# ======================================================================================
# The per-runtime manager (owns eligibility + sessions) + the ``has_megakernel`` / ``decode`` API.
# ======================================================================================
class _MegakernelDecodeManager:
    """Owns the whole-model decode megakernel sessions for one runtime (one loaded ``text`` model).

    Determines eligibility once (model kind, CUDA, arch, deploy-SM variant, enable table), then holds
    at most one lazily-built session per enabled bucket. Eligibility misses disable the bucket;
    genuine build and launch failures are surfaced."""

    def __init__(self, model_name: str, text: Any, tc: Any, device: torch.device,
                 page_table: Any, max_seq_length: int) -> None:
        self._text_ref = ref(text)
        self._tc = tc
        self._device = device
        self._page_table = page_table
        self._max_seq_length = int(max_seq_length)
        self._sessions: dict[tuple[int, bool], Any] = {}
        self._enabled_buckets: frozenset[int] = frozenset()
        self._enable_row: Optional[_EnableRow] = None
        self._num_ctas: Optional[int] = None

        self._model_kind = _model_kind(model_name)
        if self._model_kind is None:
            return
        if device.type != "cuda" or not torch.cuda.is_available():
            return
        props = torch.cuda.get_device_properties(device.index or 0)
        arch = props.major * 10
        num_ctas = select_num_ctas(arch, props.multi_processor_count)
        if num_ctas is None:
            return
        self._num_ctas = int(num_ctas)
        self._enable_row = _enable_row(self._model_kind, arch, self._num_ctas)
        self._enabled_buckets = _enabled_buckets(self._model_kind, arch, self._num_ctas)
        if self._enabled_buckets:
            logger.info(
                "megakernel decode enabled: %s sm%d ctas=%d buckets=%s (session builds lazily on "
                "the first decode for a bucket)",
                self._model_kind, arch, self._num_ctas, sorted(self._enabled_buckets))

    def bucket_enabled(self, bucket: int) -> bool:
        return int(bucket) in self._enabled_buckets

    # -- config + lazy build ---------------------------------------------------------------
    def _config(self) -> MegakernelDecodeConfig:
        ns = self._enable_row.qmma_num_stages if self._enable_row is not None else 3
        if self._model_kind == "moondream2":
            return MegakernelDecodeConfig(qmma_num_stages=ns)
        return MegakernelDecodeConfig(qmma_num_stages=ns)

    def _session(
        self,
        bucket: int,
        batch_idx: torch.Tensor,
        input_pos: torch.Tensor,
        runtime_tensors: Optional[Mapping[str, torch.Tensor]] = None,
    ) -> Any:
        """Build (once) and return the session for ``bucket``. The first call for a bucket compiles /
        loads the kernel and allocates the persistent buffers. A build failure disables the bucket and
        raises (``MegakernelNotEligible`` for an ineligibility, the original exception for a genuine
        failure)."""
        session_key = (int(bucket), runtime_tensors is not None)
        sess = self._sessions.get(session_key)
        if sess is not None:
            return sess
        text = self._text_ref()
        if text is None:
            raise MegakernelNotEligible("megakernel model was released before session build")
        try:
            # Session identity is capacity/configuration, never the first row's runtime position.
            # Per-step positions are rebound immediately before launch, so use the canonical first
            # position here and keep transient long-context requests out of the build-failure path.
            sess = build_decode_session(
                self._model_kind, text, self._tc, None, self._page_table,
                batch_idx[: int(bucket)], batch_bucket=int(bucket), seqlen=1,
                input_pos=input_pos[: int(bucket)],
                device=self._device, ctas_per_row=self._num_ctas,
                compiler_kind=self._enable_row.compiler_kind,
                config=self._config(),
                kv_capacity=self._max_seq_length,
                runtime_tensors=runtime_tensors)
        except MegakernelNotEligible as exc:
            logger.info("megakernel bucket %d not eligible (%s)", bucket, exc)
            self._enabled_buckets = self._enabled_buckets - {int(bucket)}
            raise
        except Exception as exc:  # genuine build failure: disable the bucket and surface the error
            logger.warning("megakernel bucket %d build failed (%s)", bucket, exc)
            self._enabled_buckets = self._enabled_buckets - {int(bucket)}
            raise
        self._sessions[session_key] = sess
        return sess

    @staticmethod
    def _cpu_values(name: str, values: torch.Tensor, bucket: int) -> tuple[int, ...]:
        """Read canonical scheduler controls without ever touching their device copies."""
        if not isinstance(values, torch.Tensor) or values.device.type != "cpu":
            raise TypeError(f"{name} must be an engine-owned CPU tensor")
        if values.dtype not in {
            torch.int8, torch.uint8, torch.int16, torch.int32, torch.int64,
        }:
            raise TypeError(f"{name} must have an integer dtype")
        flat = values.reshape(-1)
        if flat.numel() < int(bucket):
            raise ValueError(
                f"{name} has {flat.numel()} values, fewer than decode bucket {int(bucket)}")
        return tuple(int(value) for value in flat[: int(bucket)].tolist())

    def _validate_decode_extents(
        self,
        kv_capacity: int,
        batch_idx_cpu: tuple[int, ...],
        input_pos_cpu: tuple[int, ...],
    ) -> None:
        """Reject rows that the selected kernel or the engine allocation cannot address.

        Both inputs are the scheduler's authoritative host controls from before its packed H2D copy.
        ``PageTable.capacity`` is the allocator's existing host ledger. Consequently this check adds
        no device read, synchronization, page reservation, or megakernel-owned shadow state.
        """
        capacity = getattr(self._page_table, "capacity", None)
        if capacity is None:
            raise TypeError("page_table must expose its host-side per-row capacity ledger")
        if isinstance(capacity, torch.Tensor) and capacity.device.type != "cpu":
            raise TypeError("page_table.capacity must be host-resident")

        kv_capacity = int(kv_capacity)
        if kv_capacity <= 0:
            raise MegakernelNotEligible(
                f"megakernel has invalid KV capacity {kv_capacity}")
        for row, position in zip(batch_idx_cpu, input_pos_cpu):
            if row < 0 or row >= len(capacity):
                raise MegakernelNotEligible(
                    f"decode page-table row {row} is outside [0, {len(capacity)})")
            if position < 0 or position >= kv_capacity:
                raise MegakernelNotEligible(
                    f"decode position {position} is outside the megakernel's baked KV extent "
                    f"[0, {kv_capacity})")
            # Row zero is the engine's initialized padding/no-op row, not an admitted sequence, and
            # therefore intentionally has no allocator reservation in ``capacity``.
            if row != 0 and position >= int(capacity[row]):
                raise MegakernelNotEligible(
                    f"decode position {position} reaches page-table row {row}'s reserved KV extent "
                    f"{int(capacity[row])}")

    # -- the decode step -------------------------------------------------------------------
    def decode(self, bucket: int, embeds: torch.Tensor, batch_idx: torch.Tensor,
               input_pos: torch.Tensor, batch_idx_cpu: torch.Tensor,
               input_pos_cpu: torch.Tensor, *,
               runtime_tensors: Optional[Mapping[str, torch.Tensor]] = None) -> torch.Tensor:
        """Run one decode token through the megakernel; return the hidden ``[B, 1, H]``. Builds the
        session lazily on the first call for ``bucket``. Raises when the bucket is not enabled or a
        genuine build/launch failure occurs. ``has_megakernel`` is the no-build ship gate.
        ``batch_idx`` and
        ``input_pos`` are the engine-owned device tensors also consumed by native decode;
        ``batch_idx_cpu`` / ``input_pos_cpu`` are their authoritative scheduler-side staging
        values.
        The latter make the variant/allocation extent guard host-only and synchronization-free."""
        if not self.bucket_enabled(bucket):
            raise MegakernelNotEligible(
                f"bucket {bucket} not enabled for {self._model_kind} sm-variant ctas={self._num_ctas}")
        b = int(bucket)
        idx = self._cpu_values("batch_idx_cpu", batch_idx_cpu, b)
        pos = self._cpu_values("input_pos_cpu", input_pos_cpu, b)
        self._validate_decode_extents(self._max_seq_length, idx, pos)
        sess = self._session(bucket, batch_idx, input_pos, runtime_tensors)
        if int(sess.kv_capacity) != self._max_seq_length:
            self._validate_decode_extents(int(sess.kv_capacity), idx, pos)
        step = _DecodeStep(embed=embeds, position=input_pos, position_cpu=pos[0])
        if runtime_tensors is not None:
            sess.bind_runtime_tensors(runtime_tensors)
        global _LAUNCH_COUNT
        _LAUNCH_COUNT += 1
        return sess.decode(step, batch_idx)

    def decode_token(self, bucket: int, embeds: torch.Tensor, batch_idx: torch.Tensor,
                     input_pos: torch.Tensor, batch_idx_cpu: torch.Tensor,
                     input_pos_cpu: torch.Tensor) -> torch.Tensor:
        """TAIL-FOLD (Stage B2): run one decode token and return the DEVICE greedy token slot ``[B]``
        int32 the megakernel's in-kernel argmax wrote (read async -- no host argmax + ``.item()`` on
        the decode critical path). Same metadata and eligibility contract as ``decode``;
        RAISES on a session whose backend has no folded head (host-lm_head build)."""
        if not self.bucket_enabled(bucket):
            raise MegakernelNotEligible(
                f"bucket {bucket} not enabled for {self._model_kind} sm-variant ctas={self._num_ctas}")
        b = int(bucket)
        idx = self._cpu_values("batch_idx_cpu", batch_idx_cpu, b)
        pos = self._cpu_values("input_pos_cpu", input_pos_cpu, b)
        self._validate_decode_extents(self._max_seq_length, idx, pos)
        sess = self._session(bucket, batch_idx, input_pos)
        if int(sess.kv_capacity) != self._max_seq_length:
            self._validate_decode_extents(int(sess.kv_capacity), idx, pos)
        # Both backends define decode_token unconditionally, so hasattr cannot detect a host-lm_head
        # build; the folded head exists iff the session carries a device token slot (_token). With
        # the tail-fold deferred (vocab=0 specs) every current session is host-lm_head.
        if getattr(sess, "_token", None) is None:
            raise MegakernelNotEligible(
                "this megakernel session has no device token slot (host-lm_head backend); use decode()")
        step = _DecodeStep(embed=embeds, position=input_pos, position_cpu=pos[0])
        global _LAUNCH_COUNT
        _LAUNCH_COUNT += 1
        return sess.decode_token(step, batch_idx)


# One manager per loaded text model (its sessions + eligibility are per-model). The manager holds
# only a weak reference back to its key, so releasing a model also releases its sessions and slabs.
_MANAGERS: Any = WeakKeyDictionary()


def _manager_for(model_name: str, text: Any, tc: Any, device: torch.device, page_table: Any,
                 max_seq_length: int) -> _MegakernelDecodeManager:
    mgr = _MANAGERS.get(text)
    if mgr is None:
        mgr = _MegakernelDecodeManager(model_name, text, tc, device, page_table, max_seq_length)
        _MANAGERS[text] = mgr
    return mgr


# Number of eager megakernel launches served this process (bumped in the manager's ``decode``). A
# cheap observability hook: the integration gate reads it before/after a decode chain to PROVE the
# steps ran through the megakernel (not a replayed native graph).
_LAUNCH_COUNT = 0


def launch_count() -> int:
    """Total eager megakernel decode launches served since process start (see ``_LAUNCH_COUNT``)."""
    return _LAUNCH_COUNT


def deploy_target(model_name: str, device: torch.device) -> Optional[tuple[str, int, int]]:
    """Resolve this ``(model, device)`` to the ``(model_kind, arch, num_sms)`` of the megakernel
    variant that would serve it, or ``None`` when none fits (unknown model, non-CUDA device, or an SM
    count / arch with no shipped variant). Cheap (device-props read only), builds nothing, never
    raises. The engine resolves this once per loaded model."""
    try:
        mk = _model_kind(model_name)
        if mk is None:
            return None
        if getattr(device, "type", None) != "cuda" or not torch.cuda.is_available():
            return None
        props = torch.cuda.get_device_properties(getattr(device, "index", 0) or 0)
        arch = props.major * 10
        num_ctas = select_num_ctas(arch, props.multi_processor_count)
        if num_ctas is None:
            return None
        return (mk, int(arch), int(num_ctas))
    except Exception as exc:  # a props/query surprise is 'no megakernel here', never a hard error
        logger.warning("megakernel deploy_target(%s) failed (%s); native", model_name, exc)
        return None


@lru_cache(maxsize=None)
def _has_shipped_bundle(
    compiler_kind: str, arch: int, num_sms: int, bucket: int,
) -> bool:
    """Process-static packed-artifact preflight; never reuses or builds a loose JIT bundle."""
    from . import bundle_backend

    return bundle_backend.shipped_bundle_available(
        compiler_kind,
        int(num_sms),
        arch=f"sm{int(arch)}",
        static_extent_bindings={"active_batch": int(bucket)},
    )


def has_megakernel(model_kind: str, arch: int, num_sms: int, bucket: int) -> bool:
    """Cheap no-build gate for deployment policy plus an exact packed AOT artifact.

    A ``True`` bucket skips native CUDA-graph capture, so policy alone is insufficient: the compiler
    catalog must select one exact request identity and the corresponding host-compatible packed AOT
    wrapper must exist. Any catalog/artifact miss keeps native graph replay. Never raises.
    """
    try:
        bucket = int(bucket)
        row = _enable_row(model_kind, int(arch), int(num_sms))
        if (row is None or bucket not in row.buckets
                or not 1 <= bucket <= _MAX_MEGAKERNEL_BUCKET):
            return False
        return _has_shipped_bundle(
            row.compiler_kind, int(arch), int(num_sms), bucket)
    except Exception:
        return False


def decode(
    *,
    model_name: str,
    text: Any,
    text_config: Any,
    device: torch.device,
    page_table: Any,
    max_seq_length: int,
    batch_size: int,
    embeds: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    batch_idx_cpu: torch.Tensor,
    input_pos_cpu: torch.Tensor,
    runtime_tensors: Optional[Mapping[str, torch.Tensor]] = None,
) -> torch.Tensor:
    """Run one whole-model decode step through the megakernel; return the decoder's final hidden
    ``[B, 1, H]`` (the engine runs ``lm_head`` + sampling on it, unchanged).

    Builds the per-bucket session lazily on the first call (bundle load, or a JIT compile on a dev
    checkout), so that call is slower than steady state. Raises on ineligibility or a genuine internal
    error; it does not return ``None``. The step is eager: one launch, never captured.

      ``embeds``     -- token embedding ``[B, 1, H]`` (or ``[B, H]``).
      ``batch_idx``  -- the active rows' page-table indices ``[B]``.
      ``input_pos``  -- the active rows' current token positions ``[B]`` (== kv_len - 1).
      ``batch_idx_cpu`` / ``input_pos_cpu`` -- the scheduler's canonical host staging values for
      those device inputs. They gate baked and reserved extents without a device read.
    The device tensors are the same ones consumed by native decode."""
    mgr = _manager_for(model_name, text, text_config, device, page_table, int(max_seq_length))
    return mgr.decode(
        int(batch_size), embeds, batch_idx, input_pos, batch_idx_cpu, input_pos_cpu,
        runtime_tensors=runtime_tensors)


def decode_token(
    *,
    model_name: str,
    text: Any,
    text_config: Any,
    device: torch.device,
    page_table: Any,
    max_seq_length: int,
    batch_size: int,
    embeds: torch.Tensor,
    batch_idx: torch.Tensor,
    input_pos: torch.Tensor,
    batch_idx_cpu: torch.Tensor,
    input_pos_cpu: torch.Tensor,
) -> torch.Tensor:
    """TAIL-FOLD (Stage B2): run one whole-model decode step and return the DEVICE greedy token slot
    ``[B]`` int32 the megakernel's in-kernel argmax wrote -- the engine reads it async (no host argmax
    + ``.item()`` on the decode critical path). Same build/eligibility contract as ``decode``; RAISES
    (``MegakernelNotEligible``) when the resolved variant has no folded head (host-lm_head backend), so
    a greedy call-site must gate on this or fall back to ``decode`` + host argmax."""
    mgr = _manager_for(model_name, text, text_config, device, page_table, int(max_seq_length))
    return mgr.decode_token(
        int(batch_size), embeds, batch_idx, input_pos, batch_idx_cpu, input_pos_cpu)


